indexeddb.code:
const request = indexedDB.open("notes", 1);

request.onupgradeneeded = () => {
  request.result.createObjectStore("notes", { keyPath: "id", autoIncrement: true });
};

request.onsuccess = () => {
  const tx = request.result.transaction("notes", "readwrite");
  tx.objectStore("notes").add({ text: "Hello", created: Date.now() });
};

